<?php require 'includes/bootstrap.php';$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=(string)($_POST['password']??'');
 if (mb_strlen($name)<2 || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($pass)<8) $error='تحقق من الاسم والبريد وكلمة المرور (8 أحرف على الأقل).';
 else {try {$q=db()->prepare('INSERT INTO users (name,email,password_hash) VALUES (?,?,?)');$q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user_id']=(int)db()->lastInsertId();redirect('dashboard.php');}catch(PDOException $ex){if ($ex->getCode()==='23000')$error='البريد الإلكتروني مسجل بالفعل.';else throw $ex;}}
} header_html('إنشاء حساب'); ?>
<section class="wrapper auth-area"><div class="auth-card"><span class="eyebrow">ابدأ قصتك</span><h1>إنشاء حساب جديد</h1><?php if($error): ?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif; ?><form method="post" data-validate><?=csrf_input()?><label>الاسم الكامل<input name="name" required minlength="2" value="<?=form_value('name')?>" autocomplete="name"></label><label>البريد الإلكتروني<input type="email" name="email" required value="<?=form_value('email')?>" autocomplete="email"></label><label>كلمة المرور<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><button class="button primary full">إنشاء الحساب ↗</button></form><p>لديك حساب؟ <a href="login.php">تسجيل الدخول</a></p></div></section><?php footer_html(); ?>
